import{_ as d,o as e,c as a,a4 as r}from"./chunks/framework.BRzJ4ijD.js";const p=JSON.parse('{"title":"附录: 编码率 / 纠错能力 / SNR 实践速查","description":"","frontmatter":{},"headers":[],"relativePath":"info-theory/appendix.md","filePath":"info-theory/appendix.md","lastUpdated":1788475713000}'),n={name:"info-theory/appendix.md"};function o(i,t,s,l,c,h){return e(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="附录-编码率-纠错能力-snr-实践速查" tabindex="-1">附录: 编码率 / 纠错能力 / SNR 实践速查 <a class="header-anchor" href="#附录-编码率-纠错能力-snr-实践速查" aria-label="Permalink to &quot;附录: 编码率 / 纠错能力 / SNR 实践速查&quot;">​</a></h1><h2 id="a-1-—-code-families" tabindex="-1">A.1 — Code families <a class="header-anchor" href="#a-1-—-code-families" aria-label="Permalink to &quot;A.1 — Code families&quot;">​</a></h2><table tabindex="0"><thead><tr><th>码族</th><th>n / k</th><th>min distance</th><th>纠错能力</th><th>编码率</th><th>解码复杂度</th></tr></thead><tbody><tr><td>Hamming (7,4)</td><td>7/4</td><td>3</td><td>1 bit</td><td>4/7 ≈ 0.571</td><td>O(n)</td></tr><tr><td>Hamming SECDED (8,4)</td><td>8/4</td><td>4</td><td>1 bit 纠 / 2 bit 检</td><td>4/8 = 0.5</td><td>O(n)</td></tr><tr><td>Repetition (5,1)</td><td>5/1</td><td>5</td><td>2 bit</td><td>1/5 = 0.2</td><td>O(n) trivial</td></tr><tr><td>RS(255, 223)</td><td>255/223</td><td><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>2</mn><mi>t</mi><mo>+</mo><mn>1</mn></mrow><annotation encoding="application/x-tex">2t+1</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">2</span><span class="mord mathnormal">t</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">1</span></span></span></span></td><td>16 symbol error / 32 erasure</td><td>0.875</td><td>O(n t²)</td></tr><tr><td>BCH(255, 207)</td><td>255/207</td><td>≥17</td><td>8 bit error</td><td>0.812</td><td>O(n t²)</td></tr><tr><td>LDPC QC (8448)</td><td>6688 data</td><td>varied</td><td>near-capacity at SNR</td><td>0.5 to 0.9</td><td>O(n) BP iters</td></tr><tr><td>Polar (1024)</td><td>K (32-1024)</td><td>varies</td><td>≤ 0.5 dB Shannon dist</td><td>0.1 to 1/2</td><td>O(n log n) SCL</td></tr><tr><td>Turbo PCCC (LTE)</td><td>6144/2048</td><td>varies</td><td>1 dB Shannon dist</td><td>1/3 base; punctured 0.9</td><td>O(n) iters</td></tr><tr><td>Convolutional (K=7, rate 1/2)</td><td>streaming</td><td>varies</td><td>4-5 dB coding gain</td><td>1/2 typical</td><td>O(n) Viterbi</td></tr><tr><td>CRC32C</td><td>—</td><td>—</td><td>detect only</td><td>overhead 4 bytes / 4 KB</td><td>O(n)</td></tr><tr><td>Hamming ECC DRAM</td><td>72/64</td><td>4</td><td>1 err 纠 / 2 err 检</td><td>0.889</td><td>O(n)</td></tr></tbody></table><h2 id="a-2-—-channel-coding-choices" tabindex="-1">A.2 — Channel coding choices <a class="header-anchor" href="#a-2-—-channel-coding-choices" aria-label="Permalink to &quot;A.2 — Channel coding choices&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Use case</th><th>Code</th><th>Notes</th></tr></thead><tbody><tr><td>DRAM ECC</td><td>SECDED Hamming (72,64)</td><td>system memory universal</td></tr><tr><td>CD-ROM</td><td>CIRC RS(32,28) + RS(28,24)</td><td>interleaved robustness burst errors</td></tr><tr><td>DVD</td><td>RS-PC RS(208,192) + RS(182,172)</td><td>product code</td></tr><tr><td>QR Code</td><td>RS(40,26) baseline version 系列</td><td>shortened per block</td></tr><tr><td>DSL</td><td>RS(255,239)</td><td>string Independent ITU</td></tr><tr><td>Wi-Fi</td><td>LDPC (802.11n/ac/ax/be) + Convolutional legacy</td><td>11n+ LDPC</td></tr><tr><td>4G LTE control</td><td>咬 bite-rate pre QPP interleaver + Turbo</td><td>范本 3G/4G</td></tr><tr><td>5G NR control</td><td>Polar + CRC</td><td>short code polar decoders</td></tr><tr><td>5G NR data</td><td>LDPC + CRC</td><td>块数据充</td></tr><tr><td>Satellite DSN</td><td>RS(255,223) + Convolutional (rate 1/2, K=7)</td><td>Voyager / Cassini / Galileo</td></tr><tr><td>DVB-S2 (satellite TV)</td><td>BCH(8192,6460) + LDPC(64800,43200)</td><td>near-Shannon + 双 outer protection</td></tr><tr><td>WiMAX</td><td>RS + Convolutional</td><td>old wireless broadband</td></tr><tr><td>Storage RAID 6</td><td>RS over GF(2^8)</td><td>redundancy dual disk failure</td></tr><tr><td>ZFS raidz3</td><td>3 parity (braided RS/TP)</td><td>triple disk failure</td></tr></tbody></table><h2 id="a-3-—-modulation-and-per-bit-symbol-efficiency" tabindex="-1">A.3 — Modulation and per bit-symbol efficiency <a class="header-anchor" href="#a-3-—-modulation-and-per-bit-symbol-efficiency" aria-label="Permalink to &quot;A.3 — Modulation and per bit-symbol efficiency&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Modulation</th><th>Bits/symbol</th><th>Mandatory SNR @ BER 10⁻⁵ (uncoded)</th><th>SNR with code</th></tr></thead><tbody><tr><td>BPSK</td><td>1</td><td>9.6 dB</td><td>~2 dB w/ LDPC</td></tr><tr><td>QPSK</td><td>2</td><td>9.6 dB</td><td>~2 dB w/ LDPC</td></tr><tr><td>8-PSK</td><td>3</td><td>14 dB</td><td>~6 dB w/ LDPC</td></tr><tr><td>16-QAM</td><td>4</td><td>14.4 dB</td><td>~6.5 dB w/ LDPC</td></tr><tr><td>64-QAM</td><td>6</td><td>18.9 dB</td><td>~10 dB</td></tr><tr><td>256-QAM</td><td>8</td><td>24.4 dB</td><td>~16 dB</td></tr><tr><td>1024-QAM</td><td>10</td><td>28.4 dB</td><td>~20 dB</td></tr></tbody></table><p>→ 低 SNR 区 域 BPSK/QPSK 稳健. 64-QAM 之上须 cell edge / hot beam 同 hind sing fine structure coding with shaping or shaping.</p><h2 id="a-4-—-shannon-limit-reference-table" tabindex="-1">A.4 — Shannon limit reference table <a class="header-anchor" href="#a-4-—-shannon-limit-reference-table" aria-label="Permalink to &quot;A.4 — Shannon limit reference table&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Bandwidth</th><th>SNR</th><th>Capacity (single stream)</th><th>5G modeled peak (MIMO)</th></tr></thead><tbody><tr><td>20 MHz</td><td>10 dB</td><td>70 Mbit/s</td><td>100 (LTE Cat 4), 700 (LTE LAA)</td></tr><tr><td>100 MHz</td><td>10 dB</td><td>346 Mbit/s</td><td>700-1200 Mbit/s 4×4 MIMO</td></tr><tr><td>100 MHz</td><td>20 dB</td><td>665 Mbit/s</td><td>1500</td></tr><tr><td>400 MHz</td><td>20 dB</td><td>2663 Mbit/s</td><td>4500 mmWave MIMO</td></tr><tr><td>1 GHz (mmWave)</td><td>20 dB</td><td>6.65 Gbit/s</td><td>8-10 Gbit/s peak single phone</td></tr><tr><td>2 GHz (mmWave)</td><td>30 dB</td><td>13 Gbit/s</td><td>14-20 Gbit/s (MIMO 16 layer)</td></tr></tbody></table><p>行业 statistic 范本工 peak 5G 数达到 close to Shannon (35% under face Survey practical due to implementation loss).</p><h2 id="a-5-—-coding-gain-hierarchy" tabindex="-1">A.5 — Coding gain hierarchy <a class="header-anchor" href="#a-5-—-coding-gain-hierarchy" aria-label="Permalink to &quot;A.5 — Coding gain hierarchy&quot;">​</a></h2><p>最近 Shannon 极限 ≈ lower = 0:</p><ol><li><strong>Polar codes (SCL):</strong> ~0.5 dB at short lengths (≤ 1K)</li><li><strong>LDPC:</strong> ~0.5 dB at long lengths (≥ 10K)</li><li><strong>Turbo codes:</strong> ~0.8 dB at moderate lengths (1K-10K)</li><li><strong>RS+Conv. (Voyager):</strong> ~2-3 dB at rate 0.5</li><li><strong>BCH+RS (DVB-S2 outer BCH):</strong> ~2-4 dB hybrid concatenated</li><li><strong>Hamming (7,4):</strong> ~3 dB at cost of rate 4/7 overhead</li><li><strong>Repetition codes:</strong> linear rate half 何 巨 后成</li></ol><hr><h2 id="a-6-—-practical-implementation-references" tabindex="-1">A.6 — Practical implementation references <a class="header-anchor" href="#a-6-—-practical-implementation-references" aria-label="Permalink to &quot;A.6 — Practical implementation references&quot;">​</a></h2><ul><li><strong>Software</strong>: turbo decode <code>libturbo</code>, LDPC <code>gr-ldpc</code> <code>openairinterface5g</code>, Polar nrPolar decoder in OAI 5G PHY.</li><li><strong>Hardware accelerators</strong>: ASIC 5G Qualcomm X55-coded coding modules production polar/LDPC throughput 三code gigabaud per second.</li><li><strong>Field test tools</strong>: <code>srsRAN</code> opensource 5G NR base+ue prototype.</li><li><strong>Wireshark 调制 demod probes</strong>: Wi-Fi decoders show QAM constellation charts in real time as part of <code>QAMVisualizer</code>.</li></ul><h2 id="a-7-—-与项目其他章节交叉" tabindex="-1">A.7 — 与项目其他章节交叉 <a class="header-anchor" href="#a-7-—-与项目其他章节交叉" aria-label="Permalink to &quot;A.7 — 与项目其他章节交叉&quot;">​</a></h2><ul><li><strong>complexity.md</strong> / <strong>factoriz-ation</strong>: code <strong>distance</strong> metric leaves distance encoded trade-off among code rates.</li><li><strong>crypto/zkp.md</strong>: probabilistic checkable proofs 在 encoding castle erasure code moral distance 不可通似 proof verify independent paths.</li><li><strong>distributed/fault/erasure.md</strong>: erasure code 是 RS-based 内 correlated system communityedition 然 ML-KEM Kyber formal blowing codes.</li><li><strong>databases/olap/lakehouse.md</strong>: columns compression with zstd codecs should integrate with erasure code separate file..</li><li><strong>crypto/signatures.md</strong>: ECC DR BG agents 高 needs must frequently compatible frequency for studio bit modes.</li></ul>',19)])])}const b=d(n,[["render",o]]);export{p as __pageData,b as default};
